"""Read-only offline captured-live match tools, available at the start menu."""
from typing import Any
from mcp.types import ToolAnnotations
from .captured_match_sources import catalog_sources
from .captured_match_query import CapturedMatchQueries

queries=CapturedMatchQueries()

def register_captured_match_tools(mcp):
    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True,destructiveHint=False,openWorldHint=False))
    def fm_list_captured_match_sources() -> dict[str,Any]:
        """Discover approved named historical live-capture SQLite originals, including the exact hash-pinned Premier League shot sample from 26 October 2030 without attaching to FM. Returns exact source_id/capture_id/career_id pins, capture save date, fixture date coverage, competition IDs, available tables/columns and row counts. The29October Arsenal cup source appears only once published. These are retained live captures, distinct from the last disk save and current runtime. Available shot tables and whole-capture per-side retention states are listed when present. Registered schema-3 spatial captures expose average_positions, pass_edges, heatmap_grids, heatmap_cells, heatmap_interpolation_cells, spatial_coverage and analysis views with source states and capture timestamp. Missing columns or optional tables are unavailable, never zero. New exports require an explicit local fm-capture registration or export --register-capture; arbitrary filesystem paths are not accepted."""
        return catalog_sources()

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True,destructiveHint=False,openWorldHint=False))
    def fm_query_captured_match_data(source_id:str,capture_id:str,table:str='fixtures',fields:list[str]|None=None,
                                    career_id:str|None=None,date_from:str|None=None,date_to:str|None=None,
                                    competition_native_id:int|None=None,team_native_id:int|None=None,
                                    limit:int=100,cursor:str|None=None,grid_id:int|None=None) -> dict[str,Any]:
        """Project supported fields from one named historical live capture when FM is unavailable or at its menu. First call fm_list_captured_match_sources and supply its exact source_id/capture_id, optionally career_id. Choose one available table and column list; filters use ISO fixture dates and native competition/team IDs. team_native_id selects fixtures, so retained_players/team_totals include BOTH sides; attribute side_index0 to fixture home_team_id and side_index1 to away_team_id. Includes retained_players, player_match_analysis, team_totals, fixtures and events when captured. Registered exports expose shots, shot_map_coverage and own_goal_markers when physically present; optional tables remain unavailable in older captures. Shot defaults include raw_json with checked actor identity; filter the correct side using fixture home/away IDs before ranking expected_goals. Registered detail captures may additionally expose shot_field_coverage/shot_attempt_analysis and the separate source_observed_shots, source_observed_shot_coverage, source_observed_field_coverage and source_observed_shot_analysis tables. Source-observed counts/actors are verified but native_expected_goals is unreconciled; never add these rows to strict shots or silently use them as strict xG. Shot responses include selected per-side strict coverage and separate observed coverage for observed tables; absent retained rows are not zero. Own-goal markers are separate from attempts. Registered schema-3 spatial captures additionally expose spatial_packets, spatial_coverage, average_positions, pass_edges, heatmap_grids, heatmap_cells, heatmap_interpolation_cells, pass_edge_analysis and average_position_analysis. Resolve a player/team grid in heatmap_grids, then optionally pass its exact positive grid_id to query only that grid from heatmap_grids/heatmap_cells/heatmap_interpolation_cells; fixture/team/date filters still apply and selected_grid identifies its actual ordered side/team. Grid cells join heatmap_grids by grid_id for fixture/side/player/axes/normalization provenance. Native normalized heat intensity is not a sample count; official pass-map counts are not automatically completed-pass counts. Keep sources, coverage, normalization and UI/oracle flags distinct. Optional schema-3 retrospective tables match_period_evidence, match_periods, shot_periods, match_period_team_totals and shot_period_analysis retain verified native interval joins; they do not infer periods from elapsed minutes. expected_goals_sum_computed is derived from retained attempts, not an official halftime xG counter. Optional captured pass_attempt_sources, pass_attempt_coverage, pass_attempts, pass_path_points and pass_attempt_analysis contain counter-reconciled attempted/completed passes, distinct from official pass_edges. Join path samples to attempts by fixture_id/event_id; sampled paths are not proved origins/destinations, physical units, phases or displayed times. Coordinates and raw clock words retain unresolved units/viewpoint; do not invent a shot minute or outcome. Compute arbitrary analyses in codemode from returned rows; no caller SQL or paths are accepted. Continue every next_cursor with identical selectors/pins; deterministic pages expire after five minutes and reject changed source bytes, schema or career. Up to500 rows/256KiB per page. Report source/capture date separately from fixture date coverage and preserve unknowns. Historical participation does not prove current availability; stored goals/results do not prove causation or actual match completion."""
        return queries.query(source_id,capture_id,table,fields,career_id=career_id,date_from=date_from,date_to=date_to,
                             competition_native_id=competition_native_id,team_native_id=team_native_id,limit=limit,cursor=cursor,grid_id=grid_id)
